DG.put("ath-pakhyaan-charitr-likhyate/21",{"n":21,"title":null,"title_roman":null,"page":1109,"blocks":[{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1109,"meaning_status":"draft"},{"type":"verse","number":[1],"number_text":"੧।","page":1109,"lines":[{"gurmukhi":"ਭੂਪ ਬੰਦ ਗ੍ਰਿਹ ਨਿਜੁ ਸੁਤਹਿ ਗਹਿ ਕਰਿ ਦਿਯੋ ਪਠਾਇ।","roman":"Bhoop band grih niju suthi gahi kari diyo pathaai |","meaning_en":"The king had his own son seized and sent to prison;","page":1109,"meaning_status":"draft"},{"gurmukhi":"ਪ੍ਰਾਤ ਸਮੈ ਮੰਤ੍ਰੀ ਸਹਿਤ ਬਹੁਰੋ ਲਿਯੋ ਬੁਲਾਇ। ੧।","roman":"Praat samai mantree sahit bahuro liyo bulaai | 1 |","meaning_en":"at dawn he called him back again, together with the minister.","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[2],"number_text":"੨।","page":1109,"lines":[{"gurmukhi":"ਰੀਝ ਰਾਇ ਐਸੇ ਕਹ੍ਯੋ ਬਚਨ ਮੰਤ੍ਰਿਯਨ ਸੰਗ।","roman":"Reejh raai aise kahyo bachan mantriyan sang |","meaning_en":"Pleased, the Rai spoke these words to the ministers:","page":1109,"meaning_status":"draft"},{"gurmukhi":"ਪੁਰਖ ਤ੍ਰਿਯਨ ਚਤੁਰਨ ਚਰਿਤ ਮੋ ਸੋ ਕਰਹੁ ਪ੍ਰਸੰਗ। ੨।","roman":"Purakh triyan chaturan charit mo so karhu prasang | 2 |","meaning_en":"'Tell me tales of the wiles of clever men and women.'","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[3],"number_text":"੩।","page":1109,"lines":[{"gurmukhi":"ਤੀਰ ਸਤੁਦ੍ਰਵ ਕੇ ਹੁਤੋ ਪੁਰ ਅਨੰਦ ਇਕ ਗਾਉ।","roman":"Teer satudrav ke huto pur anand ik gaau |","meaning_en":"On the bank of the Satluj there was a town, Anandpur,","page":1109,"meaning_status":"draft","note":"ਪੁਰ ਅਨੰਦ: Anandpur."},{"gurmukhi":"ਨੇਤ੍ਰ ਤੁੰਗ ਕੇ ਢਿਗ ਬਸਤ ਕਹਲੂਰ ਕੇ ਠਾਉ। ੩।","roman":"Netr tung ke dhig basat kahloor ke thaau | 3 |","meaning_en":"lying near Naina peak, in the land of Kahlur.","page":1109,"meaning_status":"draft","note":"ਨੇਤ੍ਰ ਤੁੰਗ: 'the eye-peak', read as Naina Devi hill; uncertain."}]},{"type":"verse","number":[4],"number_text":"੪।","page":1109,"lines":[{"gurmukhi":"ਤਹਾ ਸਿਖ ਸਾਖਾ ਬਹੁਤ ਆਵਤ ਮੋਦ ਬਢਾਇ।","roman":"Tahaa sikh saakhaa bahut aavat mod badhaai |","meaning_en":"Many Sikhs and congregations came there with growing joy;","page":1109,"meaning_status":"draft","note":"ਸਾਖਾ: branches, i.e. congregations."},{"gurmukhi":"ਮਨ ਬਾਛਤ ਮੁਖਿ ਮਾਗ ਬਰ ਜਾਤ ਗ੍ਰਿਹਨ ਸੁਖ ਪਾਇ। ੪।","roman":"Man baachhat mukhi maag bar jaat grihan sukh paai | 4 |","meaning_en":"they asked aloud for the boons their hearts desired, and went home happy.","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[5],"number_text":"੫।","page":1109,"lines":[{"gurmukhi":"ਏਕ ਤ੍ਰਿਯਾ ਧਨਵੰਤ ਕੀ ਤੌਨ ਨਗਰ ਮੈ ਆਨਿ।","roman":"Ek triyaa dhanvant kee taun nagar mai aani |","meaning_en":"The wife of a rich man came into that town;","page":1109,"meaning_status":"draft"},{"gurmukhi":"ਹੇਰਿ ਰਾਇ ਪੀੜਤ ਭਈ ਬਿਧੀ ਬਿਰਹ ਕੇ ਬਾਨ। ੫।","roman":"Heri raai peerat bhaee bidhee birah ke baan | 5 |","meaning_en":"seeing the Rai she was stricken, pierced by the arrows of separation.","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[6],"number_text":"੬।","page":1109,"lines":[{"gurmukhi":"ਮਗਨ ਦਾਸ ਤਾ ਕੋ ਹੁਤੋ ਸੋ ਤਿਨ ਲਿਯੋ ਬੁਲਾਇ।","roman":"Magan daas taa ko huto so tin liyo bulaai |","meaning_en":"Magan was his servant; she called him to her,","page":1109,"meaning_status":"draft","note":"ਮਗਨ ਦਾਸ ਤਾ ਕੋ: read as 'Magan, his (the Rai's) servant'; could be a name, Magan Das."},{"gurmukhi":"ਕਛੁਕ ਦਰਬ ਤਾ ਕੋ ਦਿਯੋ ਐਸੇ ਕਹਿਯੋ ਬਨਾਇ। ੬।","roman":"Kachhuk darab taa ko diyo aise kahiyo banaai | 6 |","meaning_en":"gave him some money and spoke to him cunningly:","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[7],"number_text":"੭।","page":1109,"lines":[{"gurmukhi":"ਨਗਰ ਰਾਇ ਤੁਮਰੋ ਬਸਤ ਤਾਹਿ ਮਿਲਾਵਹੁ ਮੋਹਿ।","roman":"Nagar raai tumro basat taahi milaavhu mohi |","meaning_en":"'Your Rai lives in this town; bring me to meet him.","page":1109,"meaning_status":"draft"},{"gurmukhi":"ਤਾਹਿ ਮਿਲੇ ਦੈਹੋ ਤੁਝੈ ਅਮਿਤ ਦਰਬ ਲੈ ਤੋਹਿ। ੭।","roman":"Taahi mile daiho tujhai amit darab lai tohi | 7 |","meaning_en":"When I have met him, I will give you boundless wealth.'","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[8],"number_text":"੮।","page":1109,"lines":[{"gurmukhi":"ਮਗਨ ਲੋਭ ਧਨ ਕੇ ਲਗੇ ਆਨਿ ਰਾਵ ਕੇ ਪਾਸ।","roman":"Magan lobh dhan ke lage aani raav ke paas |","meaning_en":"Magan, gripped by greed for money, came to the Rai;","page":1109,"meaning_status":"draft"},{"gurmukhi":"ਪਰਿ ਪਾਇਨ ਕਰ ਜੋਰਿ ਕਰਿ ਇਹ ਬਿਧਿ ਕਿਯ ਅਰਦਾਸਿ। ੮।","roman":"Pari paain kar jori kari ih bidhi kiy ardaasi | 8 |","meaning_en":"falling at his feet with joined hands, he made this petition:","page":1109,"meaning_status":"draft"}]},{"type":"verse","number":[9],"number_text":"੯।","page":1109,"lines":[{"gurmukhi":"ਸਿਖ੍ਯੋ ਚਹਤ ਜੋ ਮੰਤ੍ਰ ਤੁਮ ਸੋ ਆਯੋ ਮੁਰ ਹਾਥ।","roman":"Sikhyo chahat jo mantr tum so aayo mur haath |","meaning_en":"'The mantra you wish to learn has come into my hands.","page":1109,"meaning_status":"draft"},{"gurmukhi":"ਕਹੈ ਤੁਮੈ ਸੋ ਕੀਜਿਯਹੁ ਜੁ ਕਛੁ ਤੁਹਾਰੇ ਸਾਥ। ੯।","roman":"Kahai tumai so keejiyhu ju kachhu tuhaare saath | 9 |","meaning_en":"Do whatever she tells you, whatever it may be that is to be done with you.'","page":1109,"meaning_status":"draft","note":"ਜੁ ਕਛੁ ਤੁਹਾਰੇ ਸਾਥ: literally 'whatever (is) with you'; sense uncertain."}]},{"type":"heading","kind":"chhand","name":"ਭੁਜੰਗ ਛੰਦ","gurmukhi":"ਭੁਜੰਗ ਛੰਦ","roman":"Bhujang chhand","meaning_en":"Bhujang metre.","page":1111,"meaning_status":"draft"},{"type":"verse","number":[10],"number_text":"੧੦।","page":1111,"lines":[{"gurmukhi":"ਚਲਿਯੋ ਧਾਰਿ ਆਤੀਤ ਕੋ ਭੇਸ ਰਾਈ। ਮਨਾਪਨ ਬਿਖੈ ਸ੍ਰੀ ਭਗੌਤੀ ਮਨਾਈ।","roman":"Chaliyo dhaari aateet ko bhes raaee | manaapan bikhai sree bhagautee manaaee |","meaning_en":"The Rai set out in the guise of an ascetic, invoking Sri Bhagauti in his own mind.","page":1111,"meaning_status":"draft","note":"ਆਤੀਤ: an ascetic (atit). ਮਨਾਪਨ: read as ਮਨ ਆਪਨ, 'his own mind'."},{"gurmukhi":"ਚਲਿਯੋ ਸੋਤ ਤਾ ਕੇ ਫਿਰਿਯੋ ਨਾਹਿ ਫੇਰੇ। ਧਸ੍ਯੋ ਜਾਇ ਕੈ ਵਾ ਤ੍ਰਿਯਾ ਕੇ ਸੁ ਡੇਰੇ। ੧੦।","roman":"Chaliyo sot taa ke phiriyo naahi phere | dhasyo jaai kai vaa triyaa ke su dere | 10 |","meaning_en":"He went straight on and did not turn back, and went into that woman's lodging.","page":1111,"meaning_status":"draft","note":"ਚਲਿਯੋ ਸੋਤ ਤਾ ਕੇ: read as 'went in her direction'; ਸੋਤ could also mean 'while (others) slept'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1111,"meaning_status":"draft"},{"type":"verse","number":[11],"number_text":"੧੧।","page":1111,"lines":[{"gurmukhi":"ਲਖਿ ਤ੍ਰਿਯ ਤਾਹਿ ਸੁ ਭੇਖ ਬਨਾਯੋ। ਫੂਲ ਪਾਨ ਅਰੁ ਕੈਫ ਮੰਗਾਯੋ।","roman":"Lakhi triy taahi su bhekh banaayo | phool paan aru kaiph mangaayo |","meaning_en":"Seeing him, the woman adorned herself, and sent for flowers, betel and intoxicants.","page":1111,"meaning_status":"draft","note":"ਕੈਫ: intoxicant (Arabic kaif)."},{"gurmukhi":"ਆਗੇ ਟਰਿ ਤਾ ਕੋ ਤਿਨ ਲੀਨਾ। ਚਿਤ ਕਾ ਸੋਕ ਦੂਰਿ ਕਰਿ ਦੀਨਾ। ੧੧।","roman":"Aage tari taa ko tin leenaa | chit kaa sok doori kari deenaa | 11 |","meaning_en":"She went forward to receive him, and cast away the sorrow of her heart.","page":1111,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1111,"meaning_status":"draft"},{"type":"verse","number":[12],"number_text":"੧੨।","page":1111,"lines":[{"gurmukhi":"ਬਸਤ੍ਰ ਪਹਿਰਿ ਬਹੁ ਮੋਲ ਕੇ ਅਤਿਥ ਭੇਸ ਕੋ ਡਾਰਿ।","roman":"Basatr pahiri bahu mol ke atith bhes ko daari |","meaning_en":"Putting on costly clothes and casting off the ascetic's guise,","page":1111,"meaning_status":"draft","note":"Subject unclear; read as the Rai, since he wore the ascetic's guise."},{"gurmukhi":"ਤਵਨ ਸੇਜ ਸੋਭਿਤ ਕਰੀ ਉਤਮ ਭੇਖ ਸੁਧਾਰਿ। ੧੨।","roman":"Tavan sej sobhit karee utam bhekh sudhaari | 12 |","meaning_en":"he graced that bed, in fine attire well arranged.","page":1111,"meaning_status":"draft"}]},{"type":"verse","number":[13],"number_text":"੧੩।","page":1111,"lines":[{"gurmukhi":"ਤਬ ਤਾ ਸੋ ਤ੍ਰਿਯ ਯੌ ਕਹੀ ਭੋਗ ਕਰਹੁ ਮੁਹਿ ਸਾਥ।","roman":"Tab taa so triy yau kahee bhog karhu muhi saath |","meaning_en":"Then the woman said to him: 'Make love with me.","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਪਸੁ ਪਤਾਰਿ ਦੁਖ ਦੈ ਘਨੋ ਮੈ ਬੇਚੀ ਤਵ ਹਾਥ। ੧੩।","roman":"Pasu pataari dukh dai ghano mai bechee tav haath | 13 |","meaning_en":"The foe of Pashupati, causing me great pain, has sold me into your hands.'","page":1111,"meaning_status":"draft","note":"ਪਸੁ ਪਤਾਰਿ: the enemy of Pashupati (Shiva), i.e. Kama, the god of love."}]},{"type":"verse","number":[14],"number_text":"੧੪।","page":1111,"lines":[{"gurmukhi":"ਰਾਇ ਚਿਤ ਚਿੰਤਾ ਕਰੀ ਬੈਠੇ ਤਾਹੀ ਠੌਰ।","roman":"Raai chit chintaa karee baithe taahee thaur |","meaning_en":"The Rai sat there worrying in his mind:","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਮੰਤ੍ਰ ਲੈਨ ਆਯੋ ਹੁਤੋ ਭਈ ਔਰ ਕੀ ਔਰ। ੧੪।","roman":"Mantr lain aayo huto bhaee aur kee aur | 14 |","meaning_en":"'I came to obtain a mantra, and it has turned into something else.'","page":1111,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1111,"meaning_status":"draft"},{"type":"verse","number":[15],"number_text":"੧੫।","page":1111,"lines":[{"gurmukhi":"ਭਏ ਪੂਜ ਤੋ ਕਹਾ ਗੁਮਾਨ ਨ ਕੀਜਿਯੈ।","roman":"Bhae pooj to kahaa gumaan na keejiyai |","meaning_en":"'What if one has become worshipful? One should not be proud.","page":1111,"meaning_status":"draft","note":"The Rai's words, or a general maxim."},{"gurmukhi":"ਧਨੀ ਭਏ ਤੋ ਦੁਖ੍ਯਨ ਨਿਧਨ ਨ ਦੀਜਿਯੈ।","roman":"Dhanee bhae to dukhyan nidhan na deejiyai |","meaning_en":"If one has become rich, one should not give pain to the poor.","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਰੂਪ ਭਯੋ ਤੋ ਕਹਾ ਐਂਠ ਨਹਿ ਠਾਨਿਯੈ।","roman":"Roop bhayo to kahaa ainth nahi thaaniyai |","meaning_en":"What if one has beauty? One should not be arrogant.","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਧਨ ਜੋਬਨ ਦਿਨ ਚਾਰਿ ਪਾਹੁਨੋ ਜਾਨਿਯੈ। ੧੫।","roman":"Ho dhan joban din chaari paahuno jaaniyai | 15 |","meaning_en":"Know wealth and youth to be guests for four days.'","page":1111,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1111,"meaning_status":"draft","note":"The heading names only 'chhand' (verse)."},{"type":"verse","number":[16],"number_text":"੧੬।","page":1111,"lines":[{"gurmukhi":"ਧਰਮ ਕਰੇ ਸੁਭ ਜਨਮ ਧਰਮ ਤੇ ਰੂਪਹਿ ਪੈਯੈ।","roman":"Dharam kare subh janam dharam te roophi paiyai |","meaning_en":"'By doing dharma one gains a good birth; through dharma one gains beauty.","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਧਰਮ ਕਰੇ ਧਨ ਧਾਮ ਧਰਮ ਤੇ ਰਾਜ ਸੁਹੈਯੈ।","roman":"Dharam kare dhan dhaam dharam te raaj suhaiyai |","meaning_en":"By doing dharma come wealth and home; through dharma kingship is adorned.","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿਯੋ ਤੁਹਾਰੋ ਮਾਨਿ ਧਰਮ ਕੈਸੇ ਕੈ ਛੋਰੋ।","roman":"Kahiyo tuhaaro maani dharam kaise kai chhoro |","meaning_en":"How could I give up dharma by heeding what you say?","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਮਹਾ ਨਰਕ ਕੇ ਬੀਚ ਦੇਹ ਅਪਨੀ ਕ੍ਯੋ ਬੋਰੋ। ੧੬।","roman":"Mahaa narak ke beech deh apnee kyo boro | 16 |","meaning_en":"Why should I sink my body into the great hell?'","page":1111,"meaning_status":"draft"}]},{"type":"verse","number":[17],"number_text":"੧੭।","page":1111,"lines":[{"gurmukhi":"ਕਹਿਯੋ ਤੁਮਾਰੋ ਮਾਨਿ ਭੋਗ ਤੋਸੋ ਨਹਿ ਕਰਿਹੋ।","roman":"Kahiyo tumaaro maani bhog toso nahi kariho |","meaning_en":"'Heeding what you say, I will not make love with you;","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਕੁਲਿ ਕਲੰਕ ਕੇ ਹੇਤ ਅਧਿਕ ਮਨ ਭੀਤਰ ਡਰਿਹੋ।","roman":"Kuli kalank ke het adhik man bheetar dariho |","meaning_en":"I greatly fear in my mind a stain on my lineage.","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਛੋਰਿ ਬ੍ਯਾਹਿਤਾ ਨਾਰਿ ਕੇਲ ਤੋ ਸੋ ਨ ਕਮਾਊ।","roman":"Chhori byaahitaa naari kel to so na kamaaoo |","meaning_en":"Leaving my wedded wife, I will not make love with you;","page":1111,"meaning_status":"draft"},{"gurmukhi":"ਧਰਮਰਾਜ ਕੀ ਸਭਾ ਠੌਰ ਕੈਸੇ ਕਰਿ ਪਾਊ। ੧੭।","roman":"Dharamraaj kee sabhaa thaur kaise kari paaoo | 17 |","meaning_en":"how would I find a place in the court of Dharamraj?'","page":1111,"meaning_status":"draft","note":"Dharamraj: the judge of the dead."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1111,"meaning_status":"draft"},{"type":"verse","number":[18],"number_text":"੧੮।","page":1111,"lines":[{"gurmukhi":"ਕਾਮਾਤੁਰ ਹ੍ਵੈ ਜੋ ਤ੍ਰਿਯਾ ਆਵਤ ਨਰ ਕੇ ਪਾਸ।","roman":"Kaamaatur hvai jo triyaa aavat nar ke paas |","meaning_en":"'When a woman, overcome by desire, comes to a man,","page":1111,"meaning_status":"draft","note":"The woman speaks."},{"gurmukhi":"ਮਹਾ ਨਰਕ ਸੋ ਡਾਰਿਯੈ ਦੈ ਜੋ ਜਾਨ ਨਿਰਾਸ। ੧੮।","roman":"Mahaa narak so daariyai dai jo jaan niraas | 18 |","meaning_en":"the one who lets her go disappointed should be cast into the great hell.'","page":1111,"meaning_status":"draft"}]},{"type":"verse","number":[19],"number_text":"੧੯।","page":1111,"lines":[{"gurmukhi":"ਪਾਇ ਪਰਤ ਮੋਰੋ ਸਦਾ ਪੂਜ ਕਹਤ ਹੈ ਮੋਹਿ।","roman":"Paai parat moro sadaa pooj kahat hai mohi |","meaning_en":"'You always fall at my feet and call me worshipful;","page":1111,"meaning_status":"draft","note":"The Rai speaks."},{"gurmukhi":"ਤਾ ਸੋ ਰੀਝ ਰਮ੍ਯੋ ਚਹਤ ਲਾਜ ਨ ਆਵਤ ਤੋਹਿ। ੧੯।","roman":"Taa so reejh ramyo chahat laaj na aavat tohi | 19 |","meaning_en":"are you not ashamed to want to make love with such a one?'","page":1111,"meaning_status":"draft"}]},{"type":"verse","number":[20],"number_text":"੨੦।","page":1113,"lines":[{"gurmukhi":"ਕ੍ਰਿਸਨ ਪੂਜ ਜਗ ਕੇ ਭਏ ਕੀਨੀ ਰਾਸਿ ਬਨਾਇ।","roman":"Krisan pooj jag ke bhae keenee raasi banaai |","meaning_en":"'Krishna became the one worshipped by the world, and held the Ras dance;","page":1113,"meaning_status":"draft","note":"The woman speaks."},{"gurmukhi":"ਭੋਗ ਰਾਧਿਕਾ ਸੋ ਕਰੇ ਪਰੇ ਨਰਕ ਨਹਿ ਜਾਇ। ੨੦।","roman":"Bhog raadhikaa so kare pare narak nahi jaai | 20 |","meaning_en":"he made love with Radhika, and did not go and fall into hell.'","page":1113,"meaning_status":"draft"}]},{"type":"verse","number":[21],"number_text":"੨੧।","page":1113,"lines":[{"gurmukhi":"ਪੰਚ ਤਤ ਲੈ ਬ੍ਰਹਮ ਕਰ ਕੀਨੀ ਨਰ ਕੀ ਦੇਹ।","roman":"Panch tat lai braham kar keenee nar kee deh |","meaning_en":"'Brahma took the five elements and made the human body;","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਕੀਯਾ ਆਪ ਹੀ ਤਿਨ ਬਿਖੈ ਇਸਤ੍ਰੀ ਪੁਰਖ ਸਨੇਹ। ੨੧।","roman":"Keeyaa aap hee tin bikhai istree purakh saneh | 21 |","meaning_en":"he himself put into them the love of woman and man.'","page":1113,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1113,"meaning_status":"draft"},{"type":"verse","number":[22],"number_text":"੨੨।","page":1113,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਆਨ ਰਮੋ ਮੋਹਿ ਸੰਗਾ। ਬ੍ਯਾਪਤ ਮੁਰ ਤਨ ਅਧਿਕ ਅਨੰਗਾ।","roman":"Taa te aan ramo mohi sangaa | byaapat mur tan adhik anangaa |","meaning_en":"'So come and make love with me; desire pervades my body greatly.","page":1113,"meaning_status":"draft","note":"ਅਨੰਗ: Kama, desire."},{"gurmukhi":"ਆਜ ਮਿਲੇ ਤੁਮਰੇ ਬਿਨੁ ਮਰਿਹੋ। ਬਿਰਹਾਨਲ ਕੇ ਭੀਤਰਿ ਜਰਿਹੋ। ੨੨।","roman":"Aaj mile tumre binu mariho | birhaanal ke bheetri jariho | 22 |","meaning_en":"If I do not meet you today, I shall die; I shall burn in the fire of separation.'","page":1113,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1113,"meaning_status":"draft"},{"type":"verse","number":[23],"number_text":"੨੩।","page":1113,"lines":[{"gurmukhi":"ਅੰਗ ਤੇ ਭਯੋ ਅਨੰਗ ਤੌ ਦੇਤ ਮੋਹਿ ਦੁਖ ਆਇ।","roman":"Ang te bhayo anang tau det mohi dukh aai |","meaning_en":"'From one with a body he became Ananga, the bodiless, and still he comes and gives me pain;","page":1113,"meaning_status":"draft","note":"Refers to Kama, burnt to ashes by Shiva and so called Ananga."},{"gurmukhi":"ਮਹਾ ਰੁਦ੍ਰ ਜੂ ਕੋ ਪਕਰਿ ਤਾਹਿ ਨ ਦਯੋ ਜਰਾਇ। ੨੩।","roman":"Mahaa rudr joo ko pakri taahi na dayo jaraai | 23 |","meaning_en":"did not great Rudra seize him and burn him up?'","page":1113,"meaning_status":"draft","note":"Could also be read 'why did great Rudra not seize and burn him (wholly)?'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1113,"meaning_status":"draft"},{"type":"verse","number":[24],"number_text":"੨੪।","page":1113,"lines":[{"gurmukhi":"ਧਰਹੁ ਧੀਰਜ ਮਨ ਬਾਲ ਮਦਨ ਤੁਮਰੋ ਕਸ ਕਰਿ ਹੈ।","roman":"Dharhu dheeraj man baal madan tumro kas kari hai |","meaning_en":"'Keep patience in your mind, girl; what can Madan do to you?","page":1113,"meaning_status":"draft","note":"The Rai speaks. Madan: Kama."},{"gurmukhi":"ਮਹਾ ਰੁਦ੍ਰ ਕੋ ਧ੍ਯਾਨ ਧਰੋ ਮਨ ਬੀਚ ਸੁ ਡਰਿ ਹੈ।","roman":"Mahaa rudr ko dhyaan dharo man beech su dari hai |","meaning_en":"Fix your mind in meditation on great Rudra, and he will be afraid.","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਹਮ ਨ ਤੁਮਾਰੇ ਸੰਗ ਭੋਗ ਰੁਚਿ ਮਾਨਿ ਕਰੈਗੇ।","roman":"Ham na tumaare sang bhog ruchi maani karaige |","meaning_en":"I will not make love with you with any relish;","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਯਾਗਿ ਧਰਮ ਕੀ ਨਾਰਿ ਤੋਹਿ ਕਬਹੂੰ ਨ ਬਰੈਗੇ। ੨੪।","roman":"Tyaagi dharam kee naari tohi kabhoon na baraige | 24 |","meaning_en":"I will never leave my wife of dharma and take you.'","page":1113,"meaning_status":"draft","note":"ਧਰਮ ਕੀ ਨਾਰਿ: one's lawful wife."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1113,"meaning_status":"draft"},{"type":"verse","number":[25],"number_text":"੨੫।","page":1113,"lines":[{"gurmukhi":"ਕਹਿਯੋ ਤਿਹਾਰੋ ਮਾਨਿ ਭੋਗ ਤੋਸੋ ਕ੍ਯੋ ਕਰਿਯੈ।","roman":"Kahiyo tihaaro maani bhog toso kyo kariyai |","meaning_en":"'Why should I heed what you say and make love with you?","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਘੋਰ ਨਰਕ ਕੇ ਬੀਚ ਜਾਇ ਪਰਬੇ ਤੇ ਡਰਿਯੈ।","roman":"Ghor narak ke beech jaai parbe te dariyai |","meaning_en":"One should fear going and falling into dreadful hell.","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਆਲਿੰਗਨ ਕਰੇ ਧਰਮ ਅਰਿ ਕੈ ਮੁਹਿ ਗਹਿ ਹੈ।","roman":"Tab aalingan kare dharam ari kai muhi gahi hai |","meaning_en":"If I embrace you, Dharma will seize me as its enemy,","page":1113,"meaning_status":"draft","note":"ਧਰਮ ਅਰਿ ਕੈ ਮੁਹਿ ਗਹਿ ਹੈ: read as 'Dharma(raj) will seize me as an enemy'; uncertain."},{"gurmukhi":"ਹੋ ਅਤਿ ਅਪਜਸ ਕੀ ਕਥਾ ਜਗਤ ਮੋ ਕੌ ਨਿਤਿ ਕਹਿ ਹੈ। ੨੫।","roman":"Ho ati apjas kee kathaa jagat mo kau niti kahi hai | 25 |","meaning_en":"and the world will forever tell the story of my great disgrace.'","page":1113,"meaning_status":"draft"}]},{"type":"verse","number":[26],"number_text":"੨੬।","page":1113,"lines":[{"gurmukhi":"ਚਲੈ ਨਿੰਦ ਕੀ ਕਥਾ ਬਕਤ੍ਰ ਕਸ ਤਿਸੈ ਦਿਖੈਹੋ।","roman":"Chalai nind kee kathaa bakatr kas tisai dikhaiho |","meaning_en":"'When the tale of slander goes about, how shall I show my face?","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਧਰਮ ਰਾਜ ਕੀ ਸਭਾ ਜ੍ਵਾਬ ਕੈਸੇ ਕਰਿ ਦੈਹੌ।","roman":"Dharam raaj kee sabhaa jvaab kaise kari daihau |","meaning_en":"How shall I give answer in the court of Dharamraj?","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਛਾਡਿ ਯਰਾਨਾ ਬਾਲ ਖ੍ਯਾਲ ਹਮਰੇ ਨਹਿ ਪਰਿਯੈ।","roman":"Chhaadi yaraanaa baal khyaal hamre nahi pariyai |","meaning_en":"Give up this love-affair, girl; do not pursue me.","page":1113,"meaning_status":"draft","note":"ਯਰਾਨਾ: amorous friendship (Persian yarana)."},{"gurmukhi":"ਕਹੀ ਸੁ ਹਮ ਸੋ ਕਹੀ ਬਹੁਰਿ ਯਹ ਕਹਿਯੋ ਨ ਕਰਿਯੈ। ੨੬।","roman":"Kahee su ham so kahee bahuri yah kahiyo na kariyai | 26 |","meaning_en":"What you have said, you have said to me; do not say it again.'","page":1113,"meaning_status":"draft"}]},{"type":"verse","number":[27],"number_text":"੨੭।","page":1113,"lines":[{"gurmukhi":"ਨੂਪ ਕੁਅਰਿ ਯੌ ਕਹੀ ਭੋਗ ਮੋ ਸੌ ਪਿਯ ਕਰਿਯੈ।","roman":"Noop kuari yau kahee bhog mo sau piy kariyai |","meaning_en":"Nup Kuar said this: 'Make love with me, beloved;","page":1113,"meaning_status":"draft","note":"ਨੂਪ ਕੁਅਰਿ: read as the woman's name, Nup Kuar; uncertain."},{"gurmukhi":"ਪਰੇ ਨ ਨਰਕ ਕੇ ਬੀਚ ਅਧਿਕ ਚਿਤ ਮਾਹਿ ਨ ਡਰਿਯੈ।","roman":"Pare na narak ke beech adhik chit maahi na dariyai |","meaning_en":"you will not fall into hell; do not be so afraid in your mind.","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਨਿੰਦ ਤਿਹਾਰੀ ਲੋਗ ਕਹਾ ਕਰਿ ਕੈ ਮੁਖ ਕਰਿ ਹੈ।","roman":"Nind tihaaree log kahaa kari kai mukh kari hai |","meaning_en":"How could people open their mouths to slander you?","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਤ੍ਰਾਸ ਤਿਹਾਰੇ ਸੌ ਸੁ ਅਧਿਕ ਚਿਤ ਭੀਤਰ ਡਰਿ ਹੈ। ੨੭।","roman":"Traas tihaare sau su adhik chit bheetar dari hai | 27 |","meaning_en":"They will be greatly afraid at heart for fear of you.'","page":1113,"meaning_status":"draft"}]},{"type":"verse","number":[28],"number_text":"੨੮।","page":1113,"lines":[{"gurmukhi":"ਤੌ ਕਰਿ ਹੈ ਕੋਊ ਨਿੰਦ ਕਛੂ ਜਬ ਭੇਦ ਲਹੈਂਗੇ।","roman":"Tau kari hai ko'oo nind kachhoo jab bhed lahainge |","meaning_en":"'Then will anyone slander you, when they learn the secret?","page":1113,"meaning_status":"draft","note":"Read as a rhetorical question; uncertain."},{"gurmukhi":"ਜੌ ਲਖਿ ਹੈ ਕੋਊ ਬਾਤ ਤ੍ਰਾਸ ਤੋ ਮੋਨਿ ਰਹੈਂਗੇ।","roman":"Jau lakhi hai ko'oo baat traas to moni rahainge |","meaning_en":"If anyone notices anything, they will keep silent out of fear.","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਆਜੁ ਹਮਾਰੇ ਸਾਥ ਮਿਤ੍ਰ ਰੁਚਿ ਸੌ ਰਤਿ ਕਰਿਯੈ।","roman":"Aaju hamaare saath mitr ruchi sau rati kariyai |","meaning_en":"Today, friend, make love with me with relish,","page":1113,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਨਾਤਰ ਛਾਡੌ ਟਾਂਗ ਤਰੇ ਅਬਿ ਹੋਇ ਨਿਕਰਿਯੈ। ੨੮।","roman":"Ho naatar chhaadau taang tare abi hoi nikriyai | 28 |","meaning_en":"or else give up, and go out now passing beneath my legs.'","page":1113,"meaning_status":"draft","note":"To pass beneath a woman's legs: a taunt meaning to admit oneself unmanly."}]},{"type":"verse","number":[29],"number_text":"੨੯।","page":1115,"lines":[{"gurmukhi":"ਟਾਂਗ ਤਰੇ ਸੋ ਜਾਇ ਕੇਲ ਕੈ ਜਾਹਿ ਨ ਆਵੈ।","roman":"Taang tare so jaai kel kai jaahi na aavai |","meaning_en":"'He passes beneath the legs who cannot make love,","page":1115,"meaning_status":"draft","note":"The Rai replies."},{"gurmukhi":"ਬੈਠਿ ਨਿਫੂੰਸਕ ਰਹੈ ਰੈਨਿ ਸਿਗਰੀ ਨ ਬਜਾਵੈ।","roman":"Baithi niphoonsak rahai raini sigree na bajaavai |","meaning_en":"who sits impotent and does not play all night long.","page":1115,"meaning_status":"draft","note":"ਨਿਫੂੰਸਕ: impotent. ਨ ਬਜਾਵੈ: 'does not play (an instrument)', a euphemism."},{"gurmukhi":"ਬਧੇ ਧਰਮ ਕੇ ਮੈ ਨ ਭੋਗ ਤੁਹਿ ਸਾਥ ਕਰਤ ਹੋ।","roman":"Badhe dharam ke mai na bhog tuhi saath karat ho |","meaning_en":"It is because I am bound by dharma that I do not make love with you;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਜਗ ਅਪਜਸ ਕੇ ਹੇਤ ਅਧਿਕ ਚਿਤ ਬੀਚ ਡਰਤ ਹੋ। ੨੯।","roman":"Jag apjas ke het adhik chit beech darat ho | 29 |","meaning_en":"I greatly fear in my mind the disgrace of the world.'","page":1115,"meaning_status":"draft"}]},{"type":"verse","number":[30],"number_text":"੩੦।","page":1115,"lines":[{"gurmukhi":"ਕੋਟਿ ਜਤਨ ਤੁਮ ਕਰੋ ਭਜੇ ਬਿਨੁ ਤੋਹਿ ਨ ਛੋਰੋ।","roman":"Koti jatan tum karo bhaje binu tohi na chhoro |","meaning_en":"'Make ten million efforts, I will not let you go without enjoying you;","page":1115,"meaning_status":"draft","note":"The woman speaks. ਭਜੇ: here 'enjoying'."},{"gurmukhi":"ਗਹਿ ਆਪਨ ਕਰ ਆਜੁ ਸਗਰ ਤੋ ਕੋ ਨਿਸ ਭੋਰੋ।","roman":"Gahi aapan kar aaju sagar to ko nis bhoro |","meaning_en":"holding you in my own hands, today I will keep you the whole night till dawn.","page":1115,"meaning_status":"draft","note":"ਨਿਸ ਭੋਰੋ: read as 'night till dawn'; could be 'beguile you all night'; uncertain."},{"gurmukhi":"ਮੀਤ ਤਿਹਾਰੇ ਹੇਤ ਕਾਸਿ ਕਰਵਤ ਹੂੰ ਲੈਹੋ।","roman":"Meet tihaare het kaasi karvat hoon laiho |","meaning_en":"For your sake, friend, I would even take the saw at Kashi,","page":1115,"meaning_status":"draft","note":"ਕਾਸਿ ਕਰਵਤ: the saw at Kashi (Varanasi), under which devotees once gave their lives."},{"gurmukhi":"ਹੋ ਧਰਮਰਾਜ ਕੀ ਸਭਾ ਜ੍ਵਾਬ ਠਾਢੀ ਹ੍ਵੈ ਦੈਹੋ। ੩੦।","roman":"Ho dharamraaj kee sabhaa jvaab thaadhee hvai daiho | 30 |","meaning_en":"and I will stand and give answer in the court of Dharamraj.'","page":1115,"meaning_status":"draft"}]},{"type":"verse","number":[31],"number_text":"੩੧।","page":1115,"lines":[{"gurmukhi":"ਆਜੁ ਪਿਯਾ ਤਵ ਸੰਗ ਸੇਜੁ ਰੁਚਿ ਮਾਨ ਸੁਹੈ ਹੋ।","roman":"Aaju piyaa tav sang seju ruchi maan suhai ho |","meaning_en":"'Today, beloved, I will grace the bed with you with relish;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਭਾਵਤ ਕੋ ਭੋਗ ਰੁਚਿਤ ਚਿਤ ਮਾਹਿ ਕਮੈ ਹੋ।","roman":"Man bhaavat ko bhog ruchit chit maahi kamai ho |","meaning_en":"I will make love as my heart desires, with delight in my mind.","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਆਜੁ ਸੁ ਰਤਿ ਸਭ ਰੈਨਿ ਭੋਗ ਸੁੰਦਰ ਤਵ ਕਰਿਹੋ।","roman":"Aaju su rati sabh raini bhog sundar tav kariho |","meaning_en":"Today, handsome one, I will make love with you all night,","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਸਿਵ ਬੈਰੀ ਕੋ ਦਰਪ ਸਕਲ ਮਿਲਿ ਤੁਮੈ ਪ੍ਰਹਰਿਹੋ। ੩੧।","roman":"Siv bairee ko darap sakal mili tumai prahriho | 31 |","meaning_en":"and together with you I will destroy all the pride of Shiva's foe.'","page":1115,"meaning_status":"draft","note":"ਸਿਵ ਬੈਰੀ: Shiva's enemy, Kama."}]},{"type":"heading","kind":"speaker","name":"ਰਾਇ ਬਾਚ","gurmukhi":"ਰਾਇ ਬਾਚ","roman":"Raai baach","meaning_en":"The Rai said:","page":1115,"meaning_status":"draft"},{"type":"verse","number":[32],"number_text":"੩੨।","page":1115,"lines":[{"gurmukhi":"ਪ੍ਰਥਮ ਛਤ੍ਰਿ ਕੇ ਧਾਮ ਦਿਯੋ ਬਿਧਿ ਜਨਮ ਹਮਾਰੋ।","roman":"Pratham chhatri ke dhaam diyo bidhi janam hamaaro |","meaning_en":"'First, the Creator gave me birth in a Kshatriya house;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਜਗਤ ਕੇ ਬੀਚ ਕਿਯੋ ਕੁਲ ਅਧਿਕ ਉਜਿਯਾਰੋ।","roman":"Bahuri jagat ke beech kiyo kul adhik ujiyaaro |","meaning_en":"then in the world He made my lineage greatly illustrious;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਬਹੁਰਿ ਸਭਨ ਮੈ ਬੈਠਿ ਆਪੁ ਕੋ ਪੂਜ ਕਹਾਊ।","roman":"Bahuri sabhan mai baithi aapu ko pooj kahaaoo |","meaning_en":"then, sitting among all, I am called worshipful;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਰਮੋ ਤੁਹਾਰੇ ਸਾਥ ਨੀਚ ਕੁਲ ਜਨਮਹਿ ਪਾਊ। ੩੨।","roman":"Ho ramo tuhaare saath neech kul janamhi paaoo | 32 |","meaning_en":"if I make love with you, I would get birth in a low lineage.'","page":1115,"meaning_status":"draft"}]},{"type":"verse","number":[33],"number_text":"੩੩।","page":1115,"lines":[{"gurmukhi":"ਕਹਾ ਜਨਮ ਕੀ ਬਾਤ ਜਨਮ ਸਭ ਕਰੇ ਤਿਹਾਰੇ।","roman":"Kahaa janam kee baat janam sabh kare tihaare |","meaning_en":"'What talk is this of birth? All my births are yours.","page":1115,"meaning_status":"draft","note":"The woman speaks. ਜਨਮ ਸਭ ਕਰੇ ਤਿਹਾਰੇ: literally 'all births made yours'; uncertain."},{"gurmukhi":"ਰਮੋ ਨ ਹਮ ਸੋ ਆਜੁ ਐਸ ਘਟਿ ਭਾਗ ਹਮਾਰੇ।","roman":"Ramo na ham so aaju ais ghati bhaag hamaare |","meaning_en":"You will not make love with me today; so poor is my fortune.","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਬਿਰਹ ਤਿਹਾਰੇ ਲਾਲ ਬੈਠਿ ਪਾਵਕ ਮੋ ਬਰਿਯੈ।","roman":"Birah tihaare laal baithi paavak mo bariyai |","meaning_en":"In separation from you, darling, I will sit in the fire and burn;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪੀਵ ਹਲਾਹਲ ਆਜੁ ਮਿਲੇ ਤੁਮਰੇ ਬਿਨੁ ਮਰਿਯੈ। ੩੩।","roman":"Ho peev halaahal aaju mile tumre binu mariyai | 33 |","meaning_en":"I will drink deadly poison and die today, if I do not meet you.'","page":1115,"meaning_status":"draft","note":"ਹਲਾਹਲ: a deadly poison."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1115,"meaning_status":"draft"},{"type":"verse","number":[34],"number_text":"੩੪।","page":1115,"lines":[{"gurmukhi":"ਰਾਇ ਡਰਿਯੋ ਜਉ ਦੈ ਮੁਝੈ ਸ੍ਰੀ ਭਗਵਤਿ ਕੀ ਆਨ।","roman":"Raai dariyo jau dai mujhai sree bhagavti kee aan |","meaning_en":"The Rai was afraid: 'If she binds me with an oath by Sri Bhagauti,","page":1115,"meaning_status":"draft","note":"ਆਨ: an oath. Reading of the line as the Rai's fear is uncertain."},{"gurmukhi":"ਸੰਕ ਤ੍ਯਾਗ ਯਾ ਸੋ ਰਮੋ ਕਰਿਹੌ ਨਰਕ ਪਯਾਨ। ੩੪।","roman":"Sank tyaag yaa so ramo karihau narak payaan | 34 |","meaning_en":"and I put aside my scruple and make love with her, I shall journey to hell.'","page":1115,"meaning_status":"draft"}]},{"type":"verse","number":[35],"number_text":"੩੫।","page":1115,"lines":[{"gurmukhi":"ਚਿਤ ਕੇ ਸੋਕ ਨਿਵਰਤ ਕਰਿ ਰਮੋ ਹਮਾਰੇ ਸੰਗ।","roman":"Chit ke sok nivrat kari ramo hamaare sang |","meaning_en":"'Put away the sorrow of your heart, and make love with me;","page":1115,"meaning_status":"draft","note":"The woman speaks."},{"gurmukhi":"ਮਿਲੇ ਤਿਹਾਰੇ ਬਿਨੁ ਅਧਿਕ ਬ੍ਯਾਪਤ ਮੋਹਿ ਅਨੰਗ। ੩੫।","roman":"Mile tihaare binu adhik byaapat mohi anang | 35 |","meaning_en":"without meeting you, desire pervades me greatly.'","page":1115,"meaning_status":"draft"}]},{"type":"verse","number":[36],"number_text":"੩੬।","page":1115,"lines":[{"gurmukhi":"ਨਰਕ ਪਰਨ ਤੇ ਮੈ ਡਰੋ ਕਰੋ ਨ ਤੁਮ ਸੋ ਸੰਗ।","roman":"Narak paran te mai daro karo na tum so sang |","meaning_en":"'I fear falling into hell; I will not unite with you,","page":1115,"meaning_status":"draft","note":"The Rai speaks."},{"gurmukhi":"ਤੋ ਤਨ ਮੋ ਤਨ ਕੈਸਊ ਬ੍ਯਾਪਤ ਅਧਿਕ ਅਨੰਗ। ੩੬।","roman":"To tan mo tan kaisaoo byaapat adhik anang | 36 |","meaning_en":"however greatly desire may pervade your body or mine.'","page":1115,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1115,"meaning_status":"draft"},{"type":"verse","number":[37],"number_text":"੩੭।","page":1115,"lines":[{"gurmukhi":"ਤਰੁਨ ਕਰਿਯੋ ਬਿਧਿ ਤੋਹਿ ਤਰੁਨਿ ਹੀ ਦੇਹ ਹਮਾਰੋ।","roman":"Tarun kariyo bidhi tohi taruni hee deh hamaaro |","meaning_en":"'The Creator made you young, and my body too he made young;","page":1115,"meaning_status":"draft","note":"The woman speaks."},{"gurmukhi":"ਲਖੇ ਤੁਮੈ ਤਨ ਆਜੁ ਮਦਨ ਬਸਿ ਭਯੋ ਹਮਾਰੋ।","roman":"Lakhe tumai tan aaju madan basi bhayo hamaaro |","meaning_en":"seeing you today, my body has fallen under the power of Madan.","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਕੋ ਭਰਮ ਨਿਵਾਰਿ ਭੋਗ ਮੋਰੇ ਸੰਗਿ ਕਰਿਯੈ।","roman":"Man ko bharam nivaari bhog more sangi kariyai |","meaning_en":"Cast off the doubt of your mind and make love with me;","page":1115,"meaning_status":"draft"},{"gurmukhi":"ਨਰਕ ਪਰਨ ਤੇ ਨੈਕ ਅਪਨ ਚਿਤ ਬੀਚ ਨ ਡਰਿਯੈ। ੩੭।","roman":"Narak paran te naik apan chit beech na dariyai | 37 |","meaning_en":"do not fear in your heart in the least of falling into hell.'","page":1115,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1117,"meaning_status":"draft"},{"type":"verse","number":[38],"number_text":"੩੮।","page":1117,"lines":[{"gurmukhi":"ਪੂਜ ਜਾਨਿ ਕਰ ਜੋ ਤਰੁਨਿ ਮੁਰਿ ਕੈ ਕਰਤ ਪਯਾਨ।","roman":"Pooj jaani kar jo taruni muri kai karat payaan |","meaning_en":"'The young woman who comes to me knowing me as one to be worshipped,","page":1117,"meaning_status":"draft","note":"The Rai speaks. ਮੁਰਿ ਕੈ: read as 'to me'; could be 'turning'."},{"gurmukhi":"ਤਵਨਿ ਤਰੁਨਿ ਗੁਰ ਤਵਨ ਕੀ ਲਾਗਤ ਸੁਤਾ ਸਮਾਨ। ੩੮।","roman":"Tavni taruni gur tavan kee laagat sutaa samaan | 38 |","meaning_en":"that young woman is like a daughter to that guru.'","page":1117,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1117,"meaning_status":"draft"},{"type":"verse","number":[39],"number_text":"੩੯।","page":1117,"lines":[{"gurmukhi":"ਕਹਾ ਤਰੁਨਿ ਸੋ ਪ੍ਰੀਤਿ ਨੇਹ ਨਹਿ ਓਰ ਨਿਬਾਹਹਿ।","roman":"Kahaa taruni so preeti neh nahi or nibaahhi |","meaning_en":"'What love is there with a young woman? They do not keep love to the end;","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਪੁਰਖ ਕੌ ਛਾਡਿ ਔਰ ਸੁੰਦਰ ਨਰ ਚਾਹਹਿ।","roman":"Ek purakh kau chhaadi aur sundar nar chaahhi |","meaning_en":"leaving one man, they want another handsome man.","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਅਧਿਕ ਤਰੁਨਿ ਰੁਚਿ ਮਾਨਿ ਤਰੁਨਿ ਜਾ ਸੋ ਹਿਤ ਕਰਹੀ।","roman":"Adhik taruni ruchi maani taruni jaa so hit karhee |","meaning_en":"The young man with whom a young woman, taking great delight, falls in love,","page":1117,"meaning_status":"draft","note":"First ਤਰੁਨਿ read as ਤਰੁਨ, a young man; uncertain."},{"gurmukhi":"ਹੋ ਤੁਰਤੁ ਮੂਤ੍ਰ ਕੋ ਧਾਮ ਨਗਨ ਆਗੇ ਕਰਿ ਧਰਹੀ। ੩੯।","roman":"Ho turtu mootr ko dhaam nagan aage kari dharhee | 39 |","meaning_en":"before him she at once lays bare her private parts.'","page":1117,"meaning_status":"draft","note":"ਮੂਤ੍ਰ ਕੋ ਧਾਮ: literally 'the seat of urine'."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1117,"meaning_status":"draft"},{"type":"verse","number":[40],"number_text":"੪੦।","page":1117,"lines":[{"gurmukhi":"ਕਹਾ ਕਰੌ ਕੈਸੇ ਬਚੌ ਹ੍ਰਿਦੈ ਨ ਉਪਜਤ ਸਾਤ।","roman":"Kahaa karau kaise bachau hridai na upjat saat |","meaning_en":"'What shall I do, how shall I escape? No peace arises in my heart.","page":1117,"meaning_status":"draft","note":"Speaker unclear; read as the Rai."},{"gurmukhi":"ਤੋਹਿ ਮਾਰਿ ਕੈਸੇ ਜਿਯੋ ਬਚਨ ਨੇਹ ਕੇ ਨਾਤ। ੪੦।","roman":"Tohi maari kaise jiyo bachan neh ke naat | 40 |","meaning_en":"How could I live, having caused your death, when you speak words of love?'","page":1117,"meaning_status":"draft","note":"ਬਚਨ ਨੇਹ ਕੇ ਨਾਤ: 'by the bond of words of love'; sense uncertain."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1117,"meaning_status":"draft"},{"type":"verse","number":[41],"number_text":"੪੧।","page":1117,"lines":[{"gurmukhi":"ਰਾਇ ਚਿਤ ਇਹ ਭਾਤਿ ਬਿਚਾਰੋ। ਇਹਾ ਸਿਖ ਕੋਊ ਨ ਹਮਾਰੋ।","roman":"Raai chit ih bhaati bichaaro | ihaa sikh ko'oo na hamaaro |","meaning_en":"The Rai considered in his mind thus: 'No Sikh of mine is here.","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਯਾਹਿ ਭਜੇ ਮੇਰੋ ਧ੍ਰਮ ਜਾਈ। ਭਾਜਿ ਚਲੌ ਤ੍ਰਿਯ ਦੇਤ ਗਹਾਈ। ੪੧।","roman":"Yaahi bhaje mero dhram jaaee | bhaaji chalau triy det gahaaee | 41 |","meaning_en":"If I lie with her, my dharma goes; if I run away, the woman will have me seized.","page":1117,"meaning_status":"draft","note":"ਭਜੇ: 'lie with'; ਭਾਜਿ: 'flee'."}]},{"type":"verse","number":[42],"number_text":"੪੨।","page":1117,"lines":[{"gurmukhi":"ਤਾ ਤੇ ਯਾਕੀ ਉਸਤਤਿ ਕਰੋ। ਚਰਿਤ ਖੇਲਿ ਯਾ ਕੋ ਪਰਹਰੋ।","roman":"Taa te yaakee usatti karo | charit kheli yaa ko parahro |","meaning_en":"So I will praise her, and play a trick to be rid of her.","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਬਿਨੁ ਰਤਿ ਕਰੈ ਤਰਨਿ ਜਿਯ ਮਾਰੈ। ਕਵਨ ਸਿਖ੍ਯ ਮੁਹਿ ਆਨਿ ਉਬਾਰੈ। ੪੨।","roman":"Binu rati karai tarni jiy maarai | kavan sikhy muhi aani ubaarai | 42 |","meaning_en":"If I do not make love, the young woman will take my life; what Sikh will come and save me?'","page":1117,"meaning_status":"draft","note":"ਜਿਯ ਮਾਰੈ: read as 'will kill (me)'; could be 'will kill herself'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਅੜਿਲ","gurmukhi":"ਅੜਿਲ","roman":"Aril","meaning_en":"Arril.","page":1117,"meaning_status":"draft"},{"type":"verse","number":[43],"number_text":"੪੩।","page":1117,"lines":[{"gurmukhi":"ਧੰਨ੍ਯ ਤਰੁਨਿ ਤਵ ਰੂਪ ਧੰਨ੍ਯ ਪਿਤੁ ਮਾਤ ਤਿਹਾਰੋ।","roman":"Dhanny taruni tav roop dhanny pitu maat tihaaro |","meaning_en":"'Blessed is your beauty, young woman; blessed your father and mother;","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਧੰਨ੍ਯ ਤਿਹਾਰੇ ਦੇਸ ਧੰਨ੍ਯ ਪ੍ਰਤਿਪਾਲਨ ਹਾਰੋ।","roman":"Dhanny tihaare des dhanny pratipaalan haaro |","meaning_en":"blessed is your land, blessed the one who raised you;","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਧੰਨ੍ਯ ਕੁਅਰਿ ਤਵ ਬਕ੍ਰਤ ਅਧਿਕ ਜਾ ਮੈ ਛਬਿ ਛਾਜੈ।","roman":"Dhanny kuari tav bakrat adhik jaa mai chhabi chhaajai |","meaning_en":"blessed, princess, is your face, on which great beauty shines;","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਜਲਜ ਸੂਰ ਅਰੁ ਚੰਦ੍ਰ ਦ੍ਰਪ ਕੰਦ੍ਰਪ ਲਖਿ ਭਾਜੈ। ੪੩।","roman":"Ho jalaj soor aru chandr drap kandrap lakhi bhaajai | 43 |","meaning_en":"seeing it, the lotus, the sun and the moon, and the pride of Kandarp take flight.","page":1117,"meaning_status":"draft","note":"ਜਲਜ: the lotus. Kandarp: Kama."}]},{"type":"verse","number":[44],"number_text":"੪੪।","page":1117,"lines":[{"gurmukhi":"ਸੁਭ ਸੁਹਾਗ ਤਨ ਭਰੇ ਚਾਰੁ ਚੰਚਲ ਚਖੁ ਸੋਹਹਿ।","roman":"Subh suhaag tan bhare chaaru chanchal chakhu sohhi |","meaning_en":"Your body is full of auspicious good fortune; your lovely restless eyes shine;","page":1117,"meaning_status":"draft","note":"ਸੁਹਾਗ: the good fortune of a married woman."},{"gurmukhi":"ਖਗ ਮ੍ਰਿਗ ਜਛ ਭੁਜੰਗ ਅਸੁਰ ਸੁਰ ਨਰ ਮੁਨਿ ਮੋਹਹਿ।","roman":"Khag mrig jachh bhujang asur sur nar muni mohhi |","meaning_en":"birds, deer, yakshas, serpents, demons, gods, men and sages are enchanted.","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਸਿਵ ਸਨਕਾਦਿਕ ਥਕਿਤ ਰਹਿਤ ਲਖਿ ਨੇਤ੍ਰ ਤਿਹਾਰੇ।","roman":"Siv sankaadik thakit rahit lakhi netr tihaare |","meaning_en":"Shiva and Sanak and the others stand stunned on seeing your eyes;","page":1117,"meaning_status":"draft","note":"Sanak and his brothers: celibate sages."},{"gurmukhi":"ਹੋ ਅਤਿ ਅਸਚਰਜ ਕੀ ਬਾਤ ਚੁਭਤ ਨਹਿ ਹ੍ਰਿਦੈ ਹਮਾਰੇ। ੪੪।","roman":"Ho ati asachraj kee baat chubhat nahi hridai hamaare | 44 |","meaning_en":"it is a great wonder that they do not pierce my heart.'","page":1117,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸਵੈਯਾ","gurmukhi":"ਸਵੈਯਾ","roman":"Savaiyaa","meaning_en":"Savaiya.","page":1117,"meaning_status":"draft"},{"type":"verse","number":[45],"number_text":"੪੫।","page":1117,"lines":[{"gurmukhi":"ਪੌਢਤੀ ਅੰਕ ਪ੍ਰਜੰਕ ਲਲਾ ਕੋ ਲੈ ਕਾਹੂ ਸੋ ਭੇਦ ਨ ਭਾਖਤ ਜੀ ਕੋ।","roman":"Paudhtee ank prajank lalaa ko lai kaahoo so bhed na bhaakhat jee ko |","meaning_en":"She would lie on the bed taking her darling in her arms, telling no one the secret of her heart;","page":1117,"meaning_status":"draft","note":"Speaker and reference of this savaiya are unclear; translated as printed."},{"gurmukhi":"ਕੇਲ ਕਮਾਤ ਬਹਾਤ ਸਦਾ ਨਿਸਿ ਮੈਨ ਕਲੋਲ ਨ ਲਾਗਤ ਫੀਕੋ।","roman":"Kel kamaat bahaat sadaa nisi main kalol na laagat pheeko |","meaning_en":"making love she would always pass the night, and the play of Love never seemed dull.","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਜਾਗਤ ਲਾਜ ਬਢੀ ਤਹ ਮੈ ਡਰ ਲਾਗਤ ਹੈ ਸਜਨੀ ਸਭ ਹੀ ਕੋ।","roman":"Jaagat laaj badhee tah mai dar laagat hai sajnee sabh hee ko |","meaning_en":"On waking, shame grew in her, and fear of all her friends;","page":1117,"meaning_status":"draft"},{"gurmukhi":"ਤਾ ਤੇ ਬਿਚਾਰਤ ਹੌ ਚਿਤ ਮੈ ਇਹ ਜਾਗਨ ਤੇ ਸਖਿ ਸੋਵਨ ਨੀਕੋ। ੪੫।","roman":"Taa te bichaarat hau chit mai ih jaagan te sakhi sovan neeko | 45 |","meaning_en":"so I reflect in my mind, friend: sleeping is better than this waking.","page":1117,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1119,"meaning_status":"draft"},{"type":"verse","number":[46],"number_text":"੪੬।","page":1119,"lines":[{"gurmukhi":"ਬਹੁਰ ਤ੍ਰਿਯਾ ਤਿਹ ਰਾਇ ਸੇ ਯੌ ਬਚ ਕਹਿਯੋ ਸੁਨਾਇ।","roman":"Bahur triyaa tih raai se yau bach kahiyo sunaai |","meaning_en":"Then again the woman spoke these words to the Rai:","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਆਜ ਭੋਗ ਤੋ ਸੋ ਕਰੌ ਕੈ ਮਰਿਹੌ ਬਿਖੁ ਖਾਇ। ੪੬।","roman":"Aaj bhog to so karau kai marihau bikhu khaai | 46 |","meaning_en":"'Today I will make love with you, or I will eat poison and die.'","page":1119,"meaning_status":"draft"}]},{"type":"verse","number":[47],"number_text":"੪੭।","page":1119,"lines":[{"gurmukhi":"ਬਿਸਿਖੀ ਬਰਾਬਰਿ ਨੈਨ ਤਵ ਬਿਧਨਾ ਧਰੇ ਬਨਾਇ।","roman":"Bisikhee baraabri nain tav bidhnaa dhare banaai |","meaning_en":"'The Creator made your eyes like arrows,","page":1119,"meaning_status":"draft","note":"The Rai speaks."},{"gurmukhi":"ਲਾਜ ਕੌਚ ਮੋ ਕੌ ਦਯੋ ਚੁਭਤ ਨ ਤਾ ਤੇ ਆਇ। ੪੭।","roman":"Laaj kauch mo kau dayo chubhat na taa te aai | 47 |","meaning_en":"but to me He gave the armour of shame, so they do not come and pierce me.'","page":1119,"meaning_status":"draft"}]},{"type":"verse","number":[48],"number_text":"੪੮।","page":1119,"lines":[{"gurmukhi":"ਬਨੇ ਠਨੇ ਆਵਤ ਘਨੇ ਹੇਰਤ ਹਰਤ ਗ੍ਯਾਨ।","roman":"Bane thane aavat ghane herat harat gyaan |","meaning_en":"'Many come all dressed up, stealing the wits of those who see them,","page":1119,"meaning_status":"draft","note":"The woman speaks; reading of 21.68-69 uncertain."},{"gurmukhi":"ਭੋਗ ਕਰਨ ਕੌ ਕਛੁ ਨਹੀ ਡਹਕੂ ਬੇਰ ਸਮਾਨ। ੪੮।","roman":"Bhog karan kau kachhu nahee dahkoo ber samaan | 48 |","meaning_en":"but for love-making they are nothing, mere cheats; consider the ber bush:","page":1119,"meaning_status":"draft","note":"ਡਹਕੂ: a cheat or deceiver. ਬੇਰ: the thorny jujube bush."}]},{"type":"verse","number":[49],"number_text":"੪੯।","page":1119,"lines":[{"gurmukhi":"ਧੰਨ੍ਯ ਬੇਰ ਹਮ ਤੇ ਜਗਤ ਨਿਰਖਿ ਪਥਿਕ ਕੌ ਲੇਤ।","roman":"Dhanny ber ham te jagat nirkhi pathik kau let |","meaning_en":"blessed is the ber, more than I, in this world; seeing a traveller it catches him,","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਬਰਬਸ ਖੁਆਵਤ ਫਲ ਪਕਰਿ ਜਾਨ ਬਹੁਰਿ ਘਰ ਦੇਤ। ੪੯।","roman":"Barbas khuaavat phal pakri jaan bahuri ghar det | 49 |","meaning_en":"holds him and makes him eat its fruit by force, and then lets him go home.'","page":1119,"meaning_status":"draft","note":"Sense: the thorny bush detains passers-by and feeds them, as she cannot."}]},{"type":"verse","number":[50],"number_text":"੫੦।","page":1119,"lines":[{"gurmukhi":"ਅਟਪਟਾਇ ਬਾਤੇ ਕਰੈ ਮਿਲ੍ਯੋ ਚਹਤ ਪਿਯ ਸੰਗ।","roman":"Ataptaai baate karai milyo chahat piy sang |","meaning_en":"She talks confusedly, wanting to unite with her beloved;","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਮੈਨ ਬਾਨ ਬਾਲਾ ਬਿਧੀ ਬਿਰਹ ਬਿਕਲ ਭਯੋ ਅੰਗ। ੫੦।","roman":"Main baan baalaa bidhee birah bikal bhayo ang | 50 |","meaning_en":"the girl is pierced by the arrows of Love; her body is distressed by separation.","page":1119,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਛੰਦ","gurmukhi":"ਛੰਦ","roman":"Chhand","meaning_en":"Chhand.","page":1119,"meaning_status":"draft"},{"type":"verse","number":[51],"number_text":"੫੧।","page":1119,"lines":[{"gurmukhi":"ਸੁਧਿ ਜਬ ਤੇ ਹਮ ਧਰੀ ਬਚਨ ਗੁਰ ਦਏ ਹਮਾਰੇ।","roman":"Sudhi jab te ham dharee bachan gur dae hamaare |","meaning_en":"'Ever since I gained understanding, my guru gave me these words:","page":1119,"meaning_status":"draft","note":"The Rai speaks."},{"gurmukhi":"ਪੂਤ ਇਹੈ ਪ੍ਰਨ ਤੋਹਿ ਪ੍ਰਾਨ ਜਬ ਲਗ ਘਟ ਥਾਰੇ।","roman":"Poot ihai pran tohi praan jab lag ghat thaare |","meaning_en":"\"Son, this is your vow, as long as there is life in your body:","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਨਿਜ ਨਾਰੀ ਕੇ ਸਾਥ ਨੇਹੁ ਤੁਮ ਨਿਤ ਬਢੈਯਹੁ।","roman":"Nij naaree ke saath nehu tum nit badhaiyhu |","meaning_en":"always increase your love for your own wife,","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਪਰ ਨਾਰੀ ਕੀ ਸੇਜ ਭੂਲਿ ਸੁਪਨੇ ਹੂੰ ਨ ਜੈਯਹੁ। ੫੧।","roman":"Par naaree kee sej bhooli supne hoon na jaiyhu | 51 |","meaning_en":"and never, even by mistake, even in a dream, go to the bed of another's wife.\"","page":1119,"meaning_status":"draft"}]},{"type":"verse","number":[52],"number_text":"੫੨।","page":1119,"lines":[{"gurmukhi":"ਪਰ ਨਾਰੀ ਕੇ ਭਜੇ ਸਹਸ ਬਾਸਵ ਭਗ ਪਾਏ।","roman":"Par naaree ke bhaje sahas baasav bhag paae |","meaning_en":"For lying with another's wife, Vasava received a thousand marks of the female organ;","page":1119,"meaning_status":"draft","note":"Vasava: Indra, cursed by the sage Gautam for seducing his wife Ahalya."},{"gurmukhi":"ਪਰ ਨਾਰੀ ਕੇ ਭਜੇ ਚੰਦ੍ਰ ਕਾਲੰਕ ਲਗਾਏ।","roman":"Par naaree ke bhaje chandr kaalank lagaae |","meaning_en":"for lying with another's wife, the moon was given its stain;","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਪਰ ਨਾਰੀ ਕੇ ਹੇਤ ਸੀਸ ਦਸ ਸੀਸ ਗਵਾਯੋ।","roman":"Par naaree ke het sees das sees gavaayo |","meaning_en":"for the sake of another's wife, the ten-headed one lost his heads;","page":1119,"meaning_status":"draft","note":"The ten-headed one: Ravan."},{"gurmukhi":"ਹੋ ਪਰ ਨਾਰੀ ਕੇ ਹੇਤ ਕਟਕ ਕਵਰਨ ਕੌ ਘਾਯੋ। ੫੨।","roman":"Ho par naaree ke het katak kavran kau ghaayo | 52 |","meaning_en":"for the sake of another's wife, the army of the Kauravas was slain.","page":1119,"meaning_status":"draft","note":"ਕਵਰਨ: the Kauravas."}]},{"type":"verse","number":[53],"number_text":"੫੩।","page":1119,"lines":[{"gurmukhi":"ਪਰ ਨਾਰੀ ਸੌ ਨੇਹੁ ਛੁਰੀ ਪੈਨੀ ਕਰਿ ਜਾਨਹੁ।","roman":"Par naaree sau nehu chhuree painee kari jaanhu |","meaning_en":"Know love for another's wife to be a sharp knife;","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਪਰ ਨਾਰੀ ਕੇ ਭਜੇ ਕਾਲ ਬ੍ਯਾਪਯੋ ਤਨ ਮਾਨਹੁ।","roman":"Par naaree ke bhaje kaal byaapyo tan maanhu |","meaning_en":"consider that lying with another's wife is death entering the body.","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਅਧਿਕ ਹਰੀਫੀ ਜਾਨਿ ਭੋਗ ਪਰ ਤ੍ਰਿਯ ਜੋ ਕਰਹੀ।","roman":"Adhik hareephee jaani bhog par triy jo karhee |","meaning_en":"Those who think it great cleverness to enjoy another's wife","page":1119,"meaning_status":"draft","note":"ਹਰੀਫੀ: cleverness, cunning (Persian)."},{"gurmukhi":"ਹੋ ਅੰਤ ਸ੍ਵਾਨ ਕੀ ਮ੍ਰਿਤੁ ਹਾਥ ਲੇਂਡੀ ਕੇ ਮਰਹੀ। ੫੩।","roman":"Ho ant svaan kee mritu haath lendee ke marhee | 53 |","meaning_en":"in the end die a dog's death at the hands of a wretch.","page":1119,"meaning_status":"draft","note":"ਲੇਂਡੀ: read as a base or worthless person; uncertain."}]},{"type":"verse","number":[54],"number_text":"੫੪।","page":1119,"lines":[{"gurmukhi":"ਬਾਲ ਹਮਾਰੇ ਪਾਸ ਦੇਸ ਦੇਸਨ ਤ੍ਰਿਯ ਆਵਹਿ।","roman":"Baal hamaare paas des desan triy aavhi |","meaning_en":"Girl, women come to me from many lands;","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਮਨ ਬਾਛਤ ਬਰ ਮਾਗਿ ਜਾਨਿ ਗੁਰ ਸੀਸ ਝੁਕਾਵਹਿ।","roman":"Man baachhat bar maagi jaani gur sees jhukaavhi |","meaning_en":"they ask the boons they desire and bow their heads, knowing me as guru.","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਸਿਖ੍ਯ ਪੁਤ੍ਰ ਤ੍ਰਿਯ ਸੁਤਾ ਜਾਨਿ ਅਪਨੇ ਚਿਤ ਧਰਿਯੈ।","roman":"Sikhy putr triy sutaa jaani apne chit dhariyai |","meaning_en":"I hold it in my mind that Sikhs are my sons and their women my daughters;","page":1119,"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਕਹੁ ਸੁੰਦਰਿ ਤਿਹ ਸਾਥ ਗਵਨ ਕੈਸੇ ਕਰਿ ਕਰਿਯੈ। ੫੪।","roman":"Ho kahu sundri tih saath gavan kaise kari kariyai | 54 |","meaning_en":"tell me, beautiful one, how could I go to bed with one of them?'","page":1119,"meaning_status":"draft","note":"ਗਵਨ: going, here sexual union."}]},{"type":"heading","kind":"chhand","name":"ਚੌਪਈ","gurmukhi":"ਚੌਪਈ","roman":"Chaupaee","meaning_en":"Chaupai.","page":1119,"meaning_status":"draft"},{"type":"verse","number":[55],"number_text":"੫੫।","page":1119,"lines":[{"gurmukhi":"ਬਚਨ ਸੁਨਤ ਕ੍ਰੁਧਿਤ ਤ੍ਰਿਯ ਭਈ। ਜਰਿ ਬਰਿ ਆਠ ਟੂਕ ਹ੍ਵੈ ਗਈ।","roman":"Bachan sunat krudhit triy bhaee | jari bari aath took hvai gaee |","meaning_en":"Hearing his words, the woman grew angry; she burned with rage and was torn into eight pieces.","page":1119,"meaning_status":"draft","note":"ਆਠ ਟੂਕ ਹ੍ਵੈ ਗਈ: an idiom for being beside oneself with rage."},{"gurmukhi":"ਅਬ ਹੀ ਚੋਰਿ ਚੋਰਿ ਕਹਿ ਉਠਿਹੌ। ਤੁਹਿ ਕੋਪ ਕਰਿ ਮਾਰਿ ਹੀ ਸੁਟਿਹੌ। ੫੫।","roman":"Ab hee chori chori kahi uthihau | tuhi kop kari maari hee sutihau | 55 |","meaning_en":"'Right now I will rise crying \"Thief! Thief!\", and in my anger have you killed.'","page":1119,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1121,"meaning_status":"draft"},{"type":"verse","number":[56],"number_text":"੫੬।","page":1121,"lines":[{"gurmukhi":"ਹਸਿ ਖੇਲੋ ਸੁਖ ਸੋ ਰਮੋ ਕਹਾ ਕਰਤ ਹੋ ਰੋਖ।","roman":"Hasi khelo sukh so ramo kahaa karat ho rokh |","meaning_en":"'Laugh and play, make love happily; why are you angry?","page":1121,"meaning_status":"draft","note":"The woman speaks; ਰੋਖ (anger) may refer to his stern refusal."},{"gurmukhi":"ਨੈਨ ਰਹੇ ਨਿਹੁਰਾਇ ਕ੍ਯੋ ਹੇਰਤ ਲਗਤ ਨ ਦੋਖ। ੫੬।","roman":"Nain rahe nihuraai kyo herat lagat na dokh | 56 |","meaning_en":"Why do you keep your eyes lowered? There is no sin in looking.'","page":1121,"meaning_status":"draft"}]},{"type":"verse","number":[57],"number_text":"੫੭।","page":1121,"lines":[{"gurmukhi":"ਯਾ ਤੇ ਹਮ ਹੇਰਤ ਨਹੀ ਸੁਨਿ ਸਿਖ ਹਮਾਰੇ ਬੈਨ।","roman":"Yaa te ham herat nahee suni sikh hamaare bain |","meaning_en":"'This is why I do not look; listen to my words of counsel:","page":1121,"meaning_status":"draft","note":"The Rai speaks. ਸੁਨਿ ਸਿਖ: 'hear the teaching', or 'listen, Sikh'."},{"gurmukhi":"ਲਖੇ ਲਗਨ ਲਗਿ ਜਾਇ ਜਿਨ ਬਡੇ ਬਿਰਹਿਯਾ ਨੈਨ। ੫੭।","roman":"Lakhe lagan lagi jaai jin bade birhiyaa nain | 57 |","meaning_en":"by looking, attachment takes hold, for the eyes are great lovers.'","page":1121,"meaning_status":"draft","note":"ਬਿਰਹਿਯਾ ਨੈਨ: 'love-sick eyes'; sense approximate."}]},{"type":"heading","kind":"chhand","name":"ਛਪੈ ਛੰਦ","gurmukhi":"ਛਪੈ ਛੰਦ","roman":"Chhapai chhand","meaning_en":"Chhappai.","page":1121,"meaning_status":"draft"},{"type":"verse","number":[58],"number_text":"੫੮।","page":1121,"lines":[{"gurmukhi":"ਦਿਜਨ ਦੀਜਿਯਹੁ ਦਾਨ ਦ੍ਰੁਜਨ ਕਹ ਦ੍ਰਿਸਟਿ ਦਿਖੈਯਹੁ।","roman":"Dijan deejiyhu daan drujan kah dristi dikhaiyhu |","meaning_en":"'Give alms to the twice-born; show the wicked a stern eye;","page":1121,"meaning_status":"draft","note":"ਦਿਜਨ: Brahmins. ਦ੍ਰਿਸਟਿ ਦਿਖੈਯਹੁ: read as 'show a stern look'; uncertain."},{"gurmukhi":"ਸੁਖੀ ਰਾਖਿਯਹੁ ਸਾਥ ਸਤ੍ਰੁ ਸਿਰ ਖੜਗ ਬਜੈਯਹੁ।","roman":"Sukhee raakhiyhu saath satru sir kharag bajaiyhu |","meaning_en":"keep your companions happy; strike your sword on the enemy's head;","page":1121,"meaning_status":"draft"},{"gurmukhi":"ਲੋਕ ਲਾਜ ਕਉ ਛਾਡਿ ਕਛੂ ਕਾਰਜ ਨਹਿ ਕਰਿਯਹੁ।","roman":"Lok laaj kau chhaadi kachhoo kaaraj nahi kariyhu |","meaning_en":"do nothing that casts off the regard of the people;","page":1121,"meaning_status":"draft","note":"ਲੋਕ ਲਾਜ: public honour, decency."},{"gurmukhi":"ਪਰ ਨਾਰੀ ਕੀ ਸੇਜ ਪਾਵ ਸੁਪਨੇ ਹੂੰ ਨ ਧਰਿਯਹੁ।","roman":"Par naaree kee sej paav supne hoon na dhariyhu |","meaning_en":"never, even in a dream, set foot on another's wife's bed.","page":1121,"meaning_status":"draft"},{"gurmukhi":"ਗੁਰ ਜਬ ਤੇ ਮੁਹਿ ਕਹਿਯੋ ਇਹੈ ਪ੍ਰਨ ਲਯੋ ਸੁ ਧਾਰੈ।","roman":"Gur jab te muhi kahiyo ihai pran layo su dhaarai |","meaning_en":"Ever since my guru told me this, I took this vow and hold to it:","page":1121,"flags":[{"code":"0x66","reason":"sihari typed before the previous letter's ੁ; attached to the next consonant"}],"meaning_status":"draft"},{"gurmukhi":"ਹੋ ਪਰ ਧਨ ਪਾਹਨ ਤੁਲਿ ਤ੍ਰਿਯਾ ਪਰ ਮਾਤ ਹਮਾਰੈ। ੫੮।","roman":"Ho par dhan paahan tuli triyaa par maat hamaarai | 58 |","meaning_en":"another's wealth is like stone to me, and another's wife is my mother.'","page":1121,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":1121,"meaning_status":"draft"},{"type":"verse","number":[59],"number_text":"੫੯।","page":1121,"lines":[{"gurmukhi":"ਸੁਨਤ ਰਾਵ ਕੋ ਬਚ ਸ੍ਰਵਨ ਤ੍ਰਿਯ ਮਨਿ ਅਧਿਕ ਰਿਸਾਇ।","roman":"Sunat raav ko bach sravan triy mani adhik risaai |","meaning_en":"Hearing the Rai's words with her ears, the woman grew greatly enraged at heart;","page":1121,"meaning_status":"draft"},{"gurmukhi":"ਚੋਰ ਚੋਰ ਕਹਿ ਕੈ ਉਠੀ ਸਿਖ੍ਯਨ ਦਿਯੋ ਜਗਾਇ। ੫੯।","roman":"Chor chor kahi kai uthee sikhyan diyo jagaai | 59 |","meaning_en":"she rose crying 'Thief! Thief!' and woke the Sikhs.","page":1121,"meaning_status":"draft"}]},{"type":"verse","number":[60],"number_text":"੬੦।","page":1121,"lines":[{"gurmukhi":"ਸੁਨਤ ਚੋਰ ਕੋ ਬਚ ਸ੍ਰਵਨ ਅਧਿਕ ਡਰਿਯੋ ਨਰ ਨਾਹਿ।","roman":"Sunat chor ko bach sravan adhik dariyo nar naahi |","meaning_en":"Hearing the word 'thief', the lord of men was greatly afraid;","page":1121,"meaning_status":"draft","note":"ਨਰ ਨਾਹਿ: 'lord of men', the Rai."},{"gurmukhi":"ਪਨੀ ਪਾਮਰੀ ਤਜਿ ਭਜ੍ਯੋ ਸੁਧਿ ਨ ਰਹੀ ਮਨ ਮਾਹਿ। ੬੦।","roman":"Panee paamree taji bhajyo sudhi na rahee man maahi | 60 |","meaning_en":"leaving his shoes and his shawl, he fled; he was too alarmed to think.","page":1121,"meaning_status":"draft","note":"ਪਨੀ: shoes; ਪਾਮਰੀ: a shawl or wrap."}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਚਰਿਤ੍ਰ ਪਖ੍ਯਾਨੇ ਤ੍ਰਿਯਾ ਚਰਿਤ੍ਰੇ ਮੰਤ੍ਰੀ ਭੂਪ ਸੰਬਾਦੇ ਇਕੀਸਵੋ ਚਰਿਤ੍ਰ ਸਮਾਪਤਮ","roman":"Iti sree charitr pakhyaane triyaa charitre mantree bhoop sanbaade ikeesvo charitr samaaptam","meaning_en":"Thus ends the twenty-first charitra, the dialogue of the minister and the king, of the Tria Charitra of Sri Charitropakhyan, complete.","page":1121,"meaning_status":"draft","note":"ਇਕੀਸਵੋ: twenty-first."},{"gurmukhi":"ਸਤੁ ਸੁਭਮ ਸਤੁ। ੨੧। ੪੩੯। ਅਫਜੂੰ।","roman":"Satu subham satu | 21 | 439 | aphjoon |","meaning_en":"True, auspicious, true. 21. 439. It continues.","page":1121,"meaning_status":"draft","note":"21 = charitra number; 439 = running verse total. ਅਫਜੂੰ: Persian afzun, 'increasing'."}],"page":1121,"number":[21,439]}});
